struct Foo {};
void func() {
    // Unique ownership
    std::unique_ptr<Foo> p1 = std::make_unique<Foo>();

    // Ownership transfer (move semantics)
    std::unique_ptr<Foo> p2 = std::move(p1);
    // p1 is now null.

} // Resource deleted automatically when p2 scope ends.

std::shared_ptr<int> s1 = std::make_shared<int>(42);
std::shared_ptr<int> s2 = s1; // Copy: Ref count = 2

// Access raw pointer (dangerous if misused)
int* raw = s1.get();

// Ref count drops to 1
s1.reset();

// Resource deleted when s2 scope ends (Ref count reaches 0).

auto s_ptr = std::make_shared<Data>(99);
std::weak_ptr<Data> w_ptr = s_ptr;

if (auto locked = w_ptr.lock()) {
    // Safe access: ensures resource still exists
    locked->value += 1;
}

// Resource deleted. w_ptr.lock() will now return null.

// RAII for custom non-memory resources (e.g., C handles)
struct FileCloser {
    void operator()(FILE* f) const { fclose(f); }
};

using FilePtr = std::unique_ptr<FILE, FileCloser>;
FilePtr logFile(fopen("log.txt", "w"));

if (logFile) {
    fprintf(logFile.get(), "Started.");
}
// FileCloser called automatically on destruction.
